      const p = path + "/" + DataTree.xstep(parent, n), head = [mk("span", "tk", "<" + n.name)];
      for (const a of n.attrs.slice(0, 6)) head.push(" ", mk("span", "ta", a.n), a.v === null ? "" : "=" + JSON.stringify(short(a.v)));
